'use client';

// ============================================================
// app/mobile-roadmap/[sessionId]/page.tsx
// Live Mobile Companion Webpage
//
// Rendered when the student scans the QR code from the Kiosk dashboard.
// Decodes URL-encoded base64 payload to display the exact 4-week roadmap
// generated by Gemini 3.5 Flash Lite with full offline checklist,
// PDF export/print support, and responsive touch design.
// ============================================================

import React, { useState, useEffect, useMemo, Suspense } from 'react';
import { useSearchParams, useParams } from 'next/navigation';
import {
  Sparkles,
  BookOpen,
  Video,
  FileText,
  Terminal,
  CheckCircle2,
  Circle,
  Calendar,
  Download,
  Share2,
  Printer,
  Target,
  ShieldCheck,
  ExternalLink,
  Check,
  Copy,
  GraduationCap,
  Award,
  ChevronRight,
  Clock,
} from 'lucide-react';
import { decodeRoadmapPayload, type RoadmapItemData } from '@/lib/shareUrl';

// Clean curated default fallback if page is visited without query params
const DEFAULT_ROADMAP: RoadmapItemData[] = [
  {
    week: 1,
    topic: 'Core Fundamentals of Operating Systems & CPU Architecture',
    actionItem: 'Study Process Control Blocks, CPU Scheduling algorithms, and draw thread lifecycle states.',
    resourceType: 'YouTube Video',
  },
  {
    week: 2,
    topic: 'Memory Management, Virtual Paging & Concurrency',
    actionItem: 'Implement a virtual memory page replacement simulator and solve 3 deadlock prevention problems.',
    resourceType: 'Interactive Lab',
  },
  {
    week: 3,
    topic: 'Network Protocols & System Design',
    actionItem: 'Analyze TCP/UDP socket connections, OSI layers, and debug live packet flows via Wireshark.',
    resourceType: 'Article',
  },
  {
    week: 4,
    topic: 'Placement Capstone & Mock Technical Drills',
    actionItem: 'Build an end-to-end multi-threaded server application and solve 15 targeted interview questions.',
    resourceType: 'Documentation',
  },
];

function MobileRoadmapContent() {
  const searchParams = useSearchParams();
  const params = useParams();
  const sessionId = (params?.sessionId as string) || 'live';
  const dataParam = searchParams.get('data');

  // Decode roadmap data from URL-safe base64 payload
  const decodedData = useMemo(() => {
    if (dataParam) {
      return decodeRoadmapPayload(dataParam);
    }
    return null;
  }, [dataParam]);

  const studentName = decodedData?.studentName || 'Jagadeesh Chinta';
  const goal = decodedData?.goal || 'Software Development Engineer';
  const roadmapItems =
    decodedData?.roadmap && Array.isArray(decodedData.roadmap) && decodedData.roadmap.length > 0
      ? decodedData.roadmap
      : DEFAULT_ROADMAP;

  // Local checklist state persisted per goal in localStorage
  const [completedWeeks, setCompletedWeeks] = useState<Record<number, boolean>>({});
  const [toastMessage, setToastMessage] = useState<string | null>(null);
  const [copied, setCopied] = useState<boolean>(false);

  useEffect(() => {
    try {
      const storageKey = `trialshopy_progress_${encodeURIComponent(goal.toLowerCase())}`;
      const saved = localStorage.getItem(storageKey);
      if (saved) {
        setCompletedWeeks(JSON.parse(saved));
      }
    } catch (_) {}
  }, [goal]);

  const toggleWeek = (weekNum: number) => {
    setCompletedWeeks((prev) => {
      const updated = { ...prev, [weekNum]: !prev[weekNum] };
      try {
        const storageKey = `trialshopy_progress_${encodeURIComponent(goal.toLowerCase())}`;
        localStorage.setItem(storageKey, JSON.stringify(updated));
      } catch (_) {}
      return updated;
    });
  };

  const completedCount = roadmapItems.filter((item) => completedWeeks[item.week]).length;
  const progressPct = Math.round((completedCount / (roadmapItems.length || 1)) * 100);

  const showToast = (msg: string) => {
    setToastMessage(msg);
    setTimeout(() => setToastMessage(null), 2500);
  };

  const handleCopyLink = () => {
    if (typeof window !== 'undefined') {
      navigator.clipboard?.writeText(window.location.href);
      setCopied(true);
      showToast('Roadmap link copied to clipboard!');
      setTimeout(() => setCopied(false), 2000);
    }
  };

  const handleShare = async () => {
    if (typeof navigator !== 'undefined' && navigator.share) {
      try {
        await navigator.share({
          title: `${studentName}'s ${goal} Roadmap`,
          text: `Check out my 4-Week AI Study Roadmap for ${goal}!`,
          url: window.location.href,
        });
      } catch (_) {}
    } else {
      handleCopyLink();
    }
  };

  const handlePrint = () => {
    if (typeof window !== 'undefined') {
      window.print();
    }
  };

  const getResourceDetails = (type: string) => {
    const lower = (type || '').toLowerCase();
    if (lower.includes('video') || lower.includes('youtube')) {
      return {
        icon: Video,
        color: 'text-rose-400 bg-rose-500/10 border-rose-500/20',
        label: 'Video Lecture / Walkthrough',
      };
    }
    if (lower.includes('lab') || lower.includes('interactive')) {
      return {
        icon: Terminal,
        color: 'text-emerald-400 bg-emerald-500/10 border-emerald-500/20',
        label: 'Hands-on Coding Lab',
      };
    }
    if (lower.includes('article') || lower.includes('blog')) {
      return {
        icon: FileText,
        color: 'text-amber-400 bg-amber-500/10 border-amber-500/20',
        label: 'Technical Article & Deep Dive',
      };
    }
    return {
      icon: BookOpen,
      color: 'text-indigo-400 bg-indigo-500/10 border-indigo-500/20',
      label: 'Documentation & Reference',
    };
  };

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 flex flex-col font-sans pb-16 selection:bg-indigo-500 selection:text-white">
      
      {/* ── PRINT-SPECIFIC CSS ── */}
      <style jsx global>{`
        @media print {
          body {
            background-color: #ffffff !important;
            color: #0f172a !important;
          }
          header, button, .no-print {
            display: none !important;
          }
          .print-card {
            background: #ffffff !important;
            color: #0f172a !important;
            border: 1px solid #cbd5e1 !important;
            box-shadow: none !important;
            page-break-inside: avoid;
          }
          .print-text-dark {
            color: #0f172a !important;
          }
          .print-text-muted {
            color: #475569 !important;
          }
        }
      `}</style>

      {/* ── Top Bar ─────────────────────────────────────────────── */}
      <header className="sticky top-0 z-30 bg-slate-900/90 backdrop-blur-md border-b border-slate-800/80 px-4 py-3 flex items-center justify-between no-print">
        <div className="flex items-center gap-2.5">
          <div className="h-8 w-8 rounded-xl bg-gradient-to-tr from-indigo-600 via-indigo-500 to-blue-500 flex items-center justify-center shadow-lg shadow-indigo-500/20">
            <Sparkles className="h-4 w-4 text-white" />
          </div>
          <div>
            <h1 className="text-sm font-extrabold text-white leading-tight">Trialshopy Companion</h1>
            <p className="text-[10px] text-slate-400 font-mono">Mobile Roadmap Live Sync</p>
          </div>
        </div>

        <div className="flex items-center gap-2">
          <button
            onClick={handleShare}
            aria-label="Share Roadmap"
            className="p-2 rounded-xl bg-slate-800/90 hover:bg-slate-700/90 border border-slate-700 text-slate-300 hover:text-white transition-all cursor-pointer active:scale-95"
          >
            {copied ? <Check className="w-4 h-4 text-emerald-400" /> : <Share2 className="w-4 h-4" />}
          </button>
          <button
            onClick={handlePrint}
            className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl bg-gradient-to-r from-indigo-600 to-blue-600 hover:from-indigo-500 hover:to-blue-500 text-white text-xs font-bold shadow-md cursor-pointer transition-all active:scale-95"
          >
            <Printer className="w-3.5 h-3.5" />
            <span>Print / PDF</span>
          </button>
        </div>
      </header>

      {/* ── Toast Notification ──────────────────────────────────── */}
      {toastMessage && (
        <div className="fixed top-14 left-1/2 -translate-x-1/2 z-50 px-4 py-2 rounded-full bg-indigo-600 text-white text-xs font-bold shadow-xl border border-indigo-400/40 animate-fade-in no-print flex items-center gap-2">
          <CheckCircle2 className="w-3.5 h-3.5 text-emerald-300" />
          <span>{toastMessage}</span>
        </div>
      )}

      {/* ── Student Profile & Target Goal Header Card ────────────── */}
      <div className="px-4 pt-5 pb-3">
        <div className="bg-gradient-to-br from-slate-900/95 via-indigo-950/40 to-slate-900/95 border border-indigo-500/30 rounded-3xl p-5 shadow-xl relative overflow-hidden backdrop-blur-sm print-card">
          <div className="absolute top-0 right-0 w-48 h-48 bg-indigo-500/10 rounded-full blur-3xl pointer-events-none" />

          <div className="flex items-start justify-between gap-3 relative z-10">
            <div>
              <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-[10px] font-extrabold uppercase tracking-wider bg-indigo-500/20 text-indigo-300 border border-indigo-500/30">
                <Target className="w-3 h-3 text-indigo-400" />
                <span>{goal}</span>
              </span>
              <h2 className="text-xl font-black text-white mt-2 tracking-tight print-text-dark">
                {studentName}
              </h2>
              <p className="text-xs text-slate-400 flex items-center gap-1.5 mt-0.5 print-text-muted">
                <GraduationCap className="w-3.5 h-3.5 text-slate-400" />
                <span>Lovely Professional University • B.Tech CSE</span>
              </p>
            </div>

            <div className="text-right shrink-0">
              <span className="text-[10px] uppercase font-bold text-slate-400 block tracking-wider print-text-muted">
                Completion
              </span>
              <span className="text-2xl font-black text-emerald-400">
                {progressPct}%
              </span>
            </div>
          </div>

          {/* Progress Bar */}
          <div className="mt-4 pt-4 border-t border-slate-800/80 space-y-2">
            <div className="flex justify-between text-xs text-slate-400 print-text-muted">
              <span>{completedCount} of {roadmapItems.length} weeks finished</span>
              <span className="font-mono text-indigo-300">4-Week Plan</span>
            </div>
            <div className="h-2 w-full bg-slate-800 rounded-full overflow-hidden">
              <div
                className="h-full bg-gradient-to-r from-indigo-500 via-blue-500 to-emerald-400 transition-all duration-500 rounded-full"
                style={{ width: `${progressPct}%` }}
              />
            </div>
          </div>
        </div>
      </div>

      {/* ── 4-Week Roadmap Cards ─────────────────────────────────── */}
      <div className="px-4 py-2 space-y-3.5">
        <div className="flex items-center justify-between px-1">
          <h3 className="text-xs font-bold uppercase tracking-wider text-slate-400 flex items-center gap-1.5 print-text-dark">
            <Calendar className="w-3.5 h-3.5 text-indigo-400" />
            <span>Actionable Weekly Roadmap</span>
          </h3>
          <span className="text-[11px] text-slate-500 no-print">Tap circle to check off</span>
        </div>

        {roadmapItems.map((item) => {
          const isDone = Boolean(completedWeeks[item.week]);
          const resource = getResourceDetails(item.resourceType);
          const ResourceIcon = resource.icon;

          return (
            <div
              key={item.week}
              className={`rounded-2xl border transition-all p-4.5 print-card ${
                isDone
                  ? 'bg-slate-900/40 border-emerald-500/40 shadow-[0_0_15px_rgba(16,185,129,0.1)]'
                  : 'bg-slate-900/80 border-slate-800 hover:border-slate-700/80 shadow-md'
              }`}
            >
              {/* Card Header: Week number + Checkbox */}
              <div className="flex items-center justify-between gap-3 mb-2.5">
                <div className="flex items-center gap-2">
                  <span
                    className={`px-2.5 py-1 rounded-lg text-[10px] font-black uppercase tracking-wider ${
                      isDone
                        ? 'bg-emerald-500/20 text-emerald-300 border border-emerald-500/30'
                        : 'bg-indigo-500/20 text-indigo-300 border border-indigo-500/30'
                    }`}
                  >
                    Week {item.week}
                  </span>
                  <span className="text-xs text-slate-400 font-mono print-text-muted">
                    Phase {item.week} of 4
                  </span>
                </div>

                <button
                  onClick={() => toggleWeek(item.week)}
                  aria-label={isDone ? `Mark week ${item.week} incomplete` : `Mark week ${item.week} complete`}
                  className="p-1 rounded-full text-slate-400 hover:text-white transition-colors cursor-pointer no-print"
                >
                  {isDone ? (
                    <CheckCircle2 className="w-6 h-6 text-emerald-400 drop-shadow-[0_0_8px_rgba(16,185,129,0.5)]" />
                  ) : (
                    <Circle className="w-6 h-6 text-slate-600 hover:text-slate-400 transition-colors" />
                  )}
                </button>
              </div>

              {/* Topic Title */}
              <h4
                className={`text-base font-extrabold leading-snug tracking-tight mb-2.5 print-text-dark ${
                  isDone ? 'text-slate-300 line-through' : 'text-white'
                }`}
              >
                {item.topic}
              </h4>

              {/* Action Item Box */}
              <div className="p-3 rounded-xl bg-slate-950/70 border border-slate-800/80 mb-3 text-xs text-slate-300 leading-relaxed print-card print-text-dark">
                <span className="text-[10px] font-bold uppercase tracking-wider text-indigo-400 block mb-1">
                  Actionable Objective:
                </span>
                {item.actionItem}
              </div>

              {/* Resource Badge */}
              <div className="flex items-center justify-between pt-1">
                <div
                  className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-lg text-[11px] font-semibold border ${resource.color}`}
                >
                  <ResourceIcon className="w-3.5 h-3.5 shrink-0" />
                  <span>{item.resourceType}</span>
                </div>

                <span className="text-[10px] text-slate-400 font-mono">
                  {isDone ? '✓ Completed' : 'Pending Goal'}
                </span>
              </div>
            </div>
          );
        })}
      </div>

      {/* ── Bottom Action Buttons ─────────────────────────────────── */}
      <div className="px-4 pt-4 pb-2 space-y-2.5 no-print">
        <button
          onClick={handlePrint}
          className="w-full py-4 rounded-2xl bg-gradient-to-r from-indigo-600 via-indigo-500 to-blue-600 hover:from-indigo-500 hover:to-blue-500 text-white font-extrabold text-sm shadow-[0_0_25px_rgba(99,102,241,0.4)] flex items-center justify-center gap-2.5 cursor-pointer transition-all active:scale-[0.99]"
        >
          <Printer className="w-4 h-4" />
          <span>Download Roadmap PDF / Print</span>
        </button>

        <div className="flex items-center gap-2">
          <button
            onClick={handleCopyLink}
            className="flex-1 py-3 px-4 rounded-xl bg-slate-900 border border-slate-800 text-slate-300 hover:text-white text-xs font-bold flex items-center justify-center gap-2 transition-all active:scale-98 cursor-pointer"
          >
            {copied ? <Check className="w-3.5 h-3.5 text-emerald-400" /> : <Copy className="w-3.5 h-3.5 text-slate-400" />}
            <span>{copied ? 'Link Copied!' : 'Copy Share Link'}</span>
          </button>
          <button
            onClick={handleShare}
            className="flex-1 py-3 px-4 rounded-xl bg-slate-900 border border-slate-800 text-slate-300 hover:text-white text-xs font-bold flex items-center justify-center gap-2 transition-all active:scale-98 cursor-pointer"
          >
            <Share2 className="w-3.5 h-3.5 text-indigo-400" />
            <span>Share Mobile Page</span>
          </button>
        </div>
      </div>

      {/* ── Privacy & Institutional Footer ────────────────────────── */}
      <footer className="px-6 pt-6 text-center space-y-1.5 border-t border-slate-900 mt-4">
        <div className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full bg-slate-900/80 border border-slate-800 text-[10px] text-slate-400 font-mono">
          <ShieldCheck className="w-3.5 h-3.5 text-emerald-400" />
          <span>DPDP Act 2023 Compliant • Zero Biometrics Retained</span>
        </div>
        <p className="text-[10px] text-slate-400">
          Trialshopy AI Smart Student Mentor • Lovely Professional University
        </p>
      </footer>
    </div>
  );
}

function MobileRoadmapSkeleton() {
  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 flex flex-col items-center justify-center p-6">
      <div className="h-10 w-10 rounded-2xl bg-indigo-600/30 border border-indigo-500/40 animate-pulse flex items-center justify-center mb-4">
        <Sparkles className="w-5 h-5 text-indigo-400" />
      </div>
      <p className="text-sm font-bold text-white">Loading Your Personalized Roadmap...</p>
      <p className="text-xs text-slate-400 font-mono mt-1">Decoding mobile live session</p>
    </div>
  );
}

export default function MobileRoadmapPage() {
  return (
    <Suspense fallback={<MobileRoadmapSkeleton />}>
      <MobileRoadmapContent />
    </Suspense>
  );
}
